with base as (select * from subscriptions where (customer_id = 29 and status = 'EXPIRED') or plan <> 'basic'), summary as (select date_format(start_date, 'yyyy-MM') as start_month, min(start_date) as min_start_date, count(monthly_fee) as monthly_fee_count from base group by date_format(start_date, 'yyyy-MM')) select start_month, min_start_date, monthly_fee_count from summary order by start_month
